package com.masterclass.inventory.controller; import com.masterclass.inventory.dto.CategoryDtos.*; import com.masterclass.inventory.service.CategoryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/categories") @RequiredArgsConstructor public class CategoryController { private final CategoryService service; @PostMapping public ResponseEntity<CategoryResponse> create(@Valid @RequestBody CategoryRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping public List<CategoryResponse> list(){return service.list();} @PutMapping("/{id}") public CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return service.update(id,r);} }
